import {esc,allRows,allTable,changeGuard} from './organiser-utils.js';
import {editorStyles} from './visual-editor.js';
export async function openInbox({api,sb,host,editor,status,isCurrent}){
 editorStyles();editor.replaceChildren();
 const [entries,flows,staff]=await Promise.all([allRows(api,'elan_enquiries'),allTable(sb,'elan_enquiry_workflow'),sb.rpc('elan_organiser_options')]);if(staff.error)throw staff.error;if(!isCurrent())return;
 const workflow=new Map(flows.map(r=>[r.enquiry_id,r]));let dirty=false,busy=false,page=0;changeGuard(()=>dirty,()=>busy);
 host.innerHTML=`<section class="app-card"><p class="app-badge">ORGANISER INBOX</p><h2>Keep the next step in sight.</h2><p>Notes and assignments are private to administrators. Saving here does not send an email.</p><div class="overview-filters"><label>Find enquiry<input type="search" id="inbox-search" placeholder="Name, email or message"></label><label>Assigned to<select id="inbox-assignee"><option value="">Anyone</option><option value="unassigned">Unassigned</option>${staff.data.map(s=>`<option value="${esc(s.user_id)}">${esc(s.label)}</option>`).join('')}</select></label><label>Follow-up<select id="inbox-due"><option value="">Any date</option><option value="due">Due or overdue</option><option value="planned">Scheduled</option></select></label><label>Status<select id="inbox-status"><option value="">All</option><option value="new">New</option><option value="in_progress">In progress</option><option value="resolved">Resolved</option></select></label></div><p id="inbox-count" role="status"></p><div id="inbox-results"></div></section>`;
 const q=s=>host.querySelector(s);const canChange=()=>!busy&&(!dirty||confirm('Discard the unsaved enquiry changes?'));
 function draw(){const term=q('#inbox-search').value.toLowerCase(),assigned=q('#inbox-assignee').value,due=q('#inbox-due').value,st=q('#inbox-status').value,today=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
 const matches=entries.filter(r=>{const w=workflow.get(r.id)||{};return(!term||JSON.stringify([r.full_name,r.email,r.details,w.notes]).toLowerCase().includes(term))&&(!assigned||(assigned==='unassigned'?!w.assigned_to:w.assigned_to===assigned))&&(!st||r.status===st)&&(!due||(due==='due'?w.follow_up&&w.follow_up<=today&&r.status!=='resolved':w.follow_up));}).sort((a,b)=>{const ad=workflow.get(a.id)?.follow_up||'9999',bd=workflow.get(b.id)?.follow_up||'9999';return ad.localeCompare(bd)||b.created_at.localeCompare(a.created_at);});
 const max=Math.max(0,Math.ceil(matches.length/20)-1);page=Math.min(page,max);q('#inbox-count').textContent=matches.length+' enquiries · earliest follow-up first';const result=q('#inbox-results');result.innerHTML=matches.slice(page*20,page*20+20).map(r=>{const w=workflow.get(r.id)||{};return `<article class="overview-enquiry"><div><span class="app-badge">${esc(r.kind)} · ${esc(r.status.replaceAll('_',' '))}</span><h3>${esc(r.full_name)}</h3><a href="mailto:${esc(r.email)}">${esc(r.email)}</a><p>${new Date(r.created_at).toLocaleString()}</p><details><summary>${r.details?.application_version==='2'?'Read OC application':'Read message'}</summary>${Object.entries(r.details||{}).filter(([k])=>!['application_version','intent','elan_hp','contact_consent'].includes(k)).map(([k,v])=>`<p><strong>${esc(({department:'First-choice department',second_department:'Second-choice department',responsibility_level:'Preferred responsibility',phone:'WhatsApp number',institution:'School, college or occupation',study_year:'Grade / year',age_group:'Age group',other_department:'Open to another department',motivation:'Why this department',experience:'Experience and personal contribution',work_sample:'Work sample',department_question:'Department question',department_answer:'Applicant’s response',leadership_answer:'Leadership response',weekly_hours:'Weekly availability',start_date:'Earliest start',meeting_availability:'Meeting availability',other_commitments:'Other commitments',in_person:'In-person availability',missed_deadline:'Handling a missed deadline',additional_notes:'Additional notes'})[k]||k.replaceAll('_',' '))}</strong>: ${esc(v)}</p>`).join('')}</details><button class="secondary" data-open="${r.id}">Manage enquiry</button><p>${w.follow_up?'Follow up: '+esc(w.follow_up):'No follow-up set'}<br>${esc(staff.data.find(s=>s.user_id===w.assigned_to)?.label||'Unassigned')}</p></div></article>`;}).join('')||'<p>No enquiries match.</p>';
 if(matches.length>20){const n=document.createElement('div');n.className='app-actions';n.innerHTML=`<button ${page===0?'disabled':''}>Previous</button><span>${page+1} / ${max+1}</span><button ${page===max?'disabled':''}>Next</button>`;n.firstElementChild.onclick=()=>{if(canChange()){dirty=false;editor.replaceChildren();page--;draw();}};n.lastElementChild.onclick=()=>{if(canChange()){dirty=false;editor.replaceChildren();page++;draw();}};result.append(n);}for(const b of result.querySelectorAll('[data-open]'))b.onclick=()=>{if(canChange())edit(entries.find(r=>r.id===b.dataset.open));};
 }
 function edit(row){dirty=false;const w=workflow.get(row.id)||{version:0};editor.innerHTML=`<section class="app-card"><h2>${esc(row.full_name)}</h2><form id="workflow-form"><label>Assigned organiser<select name="assigned_to"><option value="">Unassigned</option>${staff.data.map(s=>`<option value="${s.user_id}" ${s.user_id===w.assigned_to?'selected':''}>${esc(s.label)}</option>`).join('')}</select></label><label>Follow-up date<input type="date" name="follow_up" value="${esc(w.follow_up)}"></label><label>Private notes<textarea name="notes" rows="6" maxlength="6000">${esc(w.notes)}</textarea></label><button type="submit">Save organiser details</button><p role="status"></p></form><form id="workflow-status"><label>Enquiry status<select name="status">${['new','in_progress','resolved'].map(v=>`<option value="${v}" ${row.status===v?'selected':''}>${v.replaceAll('_',' ')}</option>`).join('')}</select></label><button>Save status</button><p role="status"></p></form></section>`;
 const form=editor.querySelector('#workflow-form'),sf=editor.querySelector('#workflow-status');let notesDirty=false,statusDirty=false;form.oninput=()=>{notesDirty=true;dirty=true;};sf.oninput=()=>{statusDirty=true;dirty=true;};
 form.onsubmit=async e=>{e.preventDefault();if(busy||!form.reportValidity())return;busy=true;editor.inert=true;try{const d=new FormData(form),r=await sb.rpc('elan_save_workflow',{p_id:row.id,p_assignee:d.get('assigned_to')||null,p_notes:d.get('notes'),p_follow_up:d.get('follow_up')||null,p_expected:w.version});if(r.error)throw r.error;const saved=Array.isArray(r.data)?r.data[0]:r.data;workflow.set(row.id,saved);Object.assign(w,saved);notesDirty=false;dirty=statusDirty;form.querySelector('[role=status]').textContent='Private organiser details saved.';draw();}catch(err){form.querySelector('[role=status]').textContent=err.message;}finally{busy=false;editor.inert=false;}};
 sf.onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;editor.inert=true;try{await api('enquiry-status',{id:row.id,status:sf.elements.status.value});row.status=sf.elements.status.value;statusDirty=false;dirty=notesDirty;sf.querySelector('[role=status]').textContent='Status saved.';draw();}catch(err){sf.querySelector('[role=status]').textContent=err.message;}finally{busy=false;editor.inert=false;}};editor.scrollIntoView({block:'start'});
 }
 for(const field of host.querySelectorAll('.overview-filters input,.overview-filters select')){field.dataset.previous=field.value;field.onchange=()=>{if(!canChange()){field.value=field.dataset.previous;return;}field.dataset.previous=field.value;dirty=false;editor.replaceChildren();page=0;draw();};}draw();status('');
}
